success.beforeFullFileContent:
CREATE SCHEMA IF NOT EXISTS app;

CREATE TABLE app.orders (
  order_id SERIAL PRIMARY KEY,
  user_id TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL,
  amount NUMERIC(10, 2) NOT NULL
);

-- Most rows fall in January so typical date filters stay selective; February window still populated.
INSERT INTO app.orders (user_id, created_at, amount)
SELECT
  'user_' || (random() * 1000)::int,
  CASE
    WHEN random() < 0.995 THEN '2025-01-01'::timestamptz + (random() * interval '31 days')
    ELSE '2025-02-01'::timestamptz + (random() * interval '28 days')
  END,
  (random() * 1000)::numeric(10, 2)
FROM generate_series(1, 500000);

-- Speed up: WHERE user_id = ? ORDER BY created_at (limit)
CREATE INDEX idx_orders_user_id_created_at ON app.orders (user_id, created_at DESC);

-- Speed up: WHERE created_at range ... ORDER BY created_at (index-only scan avoids heap fetches)
CREATE INDEX idx_orders_created_at ON app.orders (created_at) INCLUDE (order_id, user_id, amount);

VACUUM ANALYZE app.orders;

